import { ServiceError, USE_DB } from "./data-source";

export type ExportKind = "prospects" | "invoices" | "subscribers" | "scrape-results";
export type ExportFormat = "xlsx" | "pdf";

/** Saves a Blob through a temporary link (works for every browser, no popup). */
export function saveBlob(blob: Blob, filename: string): void {
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  link.click();
  URL.revokeObjectURL(url);
}

/**
 * `DATA_SOURCE=db`: downloads the file generated by `GET /api/exports/:kind`, which re-applies
 * the filters and the authorization on the server. Resolves to `false` in mock mode, where no
 * real file exists (the caller keeps its former notice).
 */
export async function downloadExport(
  kind: ExportKind,
  format: ExportFormat,
  filters: Record<string, string | undefined> = {},
): Promise<boolean> {
  if (!USE_DB) return false;
  const params = new URLSearchParams({ format });
  for (const [key, value] of Object.entries(filters)) if (value) params.set(key, value);

  const response = await fetch(`/api/exports/${kind}?${params}`, { credentials: "same-origin" });
  if (!response.ok) {
    let message = "L'export a échoué.";
    try {
      const body = (await response.json()) as { message?: string };
      if (body.message) message = body.message;
    } catch {
      // keep the generic message
    }
    throw new ServiceError(message, String(response.status));
  }
  const name = /filename="([^"]+)"/.exec(response.headers.get("Content-Disposition") ?? "")?.[1] ?? `export.${format}`;
  saveBlob(await response.blob(), name);
  return true;
}

/** Invoice PDF, generated on demand by `GET /api/invoices/:id/pdf`. `false` in mock mode. */
export async function downloadInvoicePdf(invoiceId: string): Promise<boolean> {
  if (!USE_DB) return false;
  const response = await fetch(`/api/invoices/${encodeURIComponent(invoiceId)}/pdf`, { credentials: "same-origin" });
  if (!response.ok) throw new ServiceError("Le PDF n'a pas pu être généré.", String(response.status));
  const name = /filename="([^"]+)"/.exec(response.headers.get("Content-Disposition") ?? "")?.[1] ?? "facture.pdf";
  saveBlob(await response.blob(), name);
  return true;
}
